package es.uma.urbanpulse.shared.storage;

/**
 * Where the evidence files live (ADR-0013). The provider is hidden behind it: the services and the
 * controllers never depend on the concrete implementation.
 *
 * <p>A key is generated by the storage, never built from user input. A key that the storage could
 * not have generated is refused with {@link IllegalArgumentException}. Any failure of the provider
 * is a {@link StorageException}.
 */
public interface StorageService {

    /** Stores the content under a new key and returns that key. */
    String put(byte[] content);

    /** The content stored under the key. */
    byte[] get(String key);

    /** Whether there is content under the key. */
    boolean exists(String key);

    /** Removes the content under the key, if there is any. */
    void delete(String key);
}
